  "./templates/default/sp_poison.htm": "想检查什么？<br>\r\n\r\n<input type=\"hidden\" name=\"mode\" value=\"special\">\r\n<input type=\"radio\" name=\"command\" id=\"menu\" value=\"menu\" checked><a onclick=sl('menu'); href=\"javascript:void(0);\" >返回</a><br><br>\r\n<!--{if $itms1 && ((strpos($itmk1,'P') === 0) || (strpos($itmk1,'H') === 0))}-->\r\n<input type=\"radio\" name=\"command\" id=\"chkp1\" value=\"chkp1\"><a onclick=sl('chkp1'); href=\"javascript:void(0);\" >$itm1 </a><br>\r\n<!--{/if}-->\r\n<!--{if $itms2 && ((strpos($itmk2,'P') === 0) || (strpos($itmk2,'H') === 0))}-->\r\n<input type=\"radio\" name=\"command\" id=\"chkp2\" value=\"chkp2\"><a onclick=sl('chkp2'); href=\"javascript:void(0);\" >$itm2 </a><br>\r\n<!--{/if}-->\r\n<!--{if $itms3 && ((strpos($itmk3,'P') === 0) || (strpos($itmk3,'H') === 0))}-->\r\n<input type=\"radio\" name=\"command\" id=\"chkp3\" value=\"chkp3\"><a onclick=sl('chkp3'); href=\"javascript:void(0);\" >$itm3 </a><br>\r\n<!--{/if}-->\r\n<!--{if $itms4 && ((strpos($itmk4,'P') === 0) || (strpos($itmk4,'H') === 0))}-->\r\n<input type=\"radio\" name=\"command\" id=\"chkp4\" value=\"chkp4\"><a onclick=sl('chkp4'); href=\"javascript:void(0);\" >$itm4 </a><br>\r\n<!--{/if}-->\r\n<!--{if $itms5 && ((strpos($itmk5,'P') === 0) || (strpos($itmk5,'H') === 0))}-->\r\n<input type=\"radio\" name=\"command\" id=\"chkp5\" value=\"chkp5\"><a onclick=sl('chkp5'); href=\"javascript:void(0);\" >$itm5 </a><br>\r\n<!--{/if}-->\r\n<!--{if $itms6 && ((strpos($itmk6,'P') === 0) || (strpos($itmk6,'H') === 0))}-->\r\n<input type=\"radio\" name=\"command\" id=\"chkp6\" value=\"chkp6\"><a onclick=sl('chkp6'); href=\"javascript:void(0);\" >$itm6 </a><br>\r\n<!--{/if}--><br><br>\r\n\r\n<input type=\"button\" class=\"cmdbutton\"  value=\"提交\" onclick=\"postCmd('gamecmd','command.php');this.disabled=true;\">",
  "./templates/default/sp_pose.htm": "想采取什么基本姿态？<br>\r\n\r\n<input type=\"hidden\" name=\"mode\" value=\"special\">\r\n<input type=\"radio\" name=\"command\" id=\"menu\" value=\"menu\" checked><a onclick=sl('menu'); href=\"javascript:void(0);\" >返回</a><br><br>\r\n<!--{loop $poseinfo $key $value}-->\r\n<!--{if $value}-->\r\n<input type=\"radio\" name=\"command\" id=\"pose$key\" value=\"pose$key\"><a onclick=sl('pose$key'); href=\"javascript:void(0);\" >$value </a><br>\r\n<!--{/if}-->\r\n<!--{/loop}-->\r\n\r\n \r\n\r\n",
  "./templates/default/sp_pswd.htm": "请输入旧密码和新密码，20个字以内。留空为不修改。<br>\r\n\r\n<input type=\"hidden\" name=\"mode\" value=\"chgpassword\">\r\n<div>旧密码：<input size=\"20\" type=\"password\" name=\"oldpswd\" maxlength=\"20\" value=\"\"></div>\r\n<br />\r\n<div>新密码：<input size=\"20\" type=\"password\" name=\"newpswd\" maxlength=\"20\" value=\"\"></div>\r\n<br />\r\n<div>重复输入：<input size=\"20\" type=\"password\" name=\"newpswd2\" maxlength=\"20\" value=\"\"></div>\r\n<br />\r\n\r\n<br />\r\n<input type=\"button\" class=\"cmdbutton\"  value=\"提交\" onclick=\"postCmd('gamecmd','command.php');this.disabled=true;\">",
